// Builds dist/data/structure-objectives.js: the missions whose objective is to
// destroy each demolition structure, with the game's Korean name and the wiki's
// difficulty range. Sources: db/source/structure_objectives.json, wiki_objectives.json
// and game_names_ko.json. Do not edit the output.
// Usage: node scripts/build-structure-objectives.mjs
import { readFile, writeFile } from 'node:fs/promises';

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));
const map = (await read('structure_objectives.json')).structures;
const wiki = await read('wiki_objectives.json');
const game = await read('game_names_ko.json');

const objectives = Object.fromEntries(Object.entries(map).map(([id, entries]) => [id, entries.map(entry => {
  const name = game.strings.objectives[entry.game];
  if (!name) throw new Error(`${id}: no game Korean for "${entry.game}" (run scripts/build-game-names.mjs)`);
  const row = wiki.cargo[entry.kind][entry.page];
  if (!row) throw new Error(`${id}: "${entry.page}" has no ${entry.kind} row in the wiki Cargo tables`);
  return { name, en: entry.game, kind: entry.kind, min: row.min, max: row.max, wiki: `https://helldivers.wiki.gg/wiki/${entry.page.replaceAll(' ', '_')}`, revision: wiki.pages[entry.page].revision };
})]));

const out = `// Generated by scripts/build-structure-objectives.mjs. Do not edit.
// Missions whose objective is to destroy the structure: main or tactical objective,
// the game's Korean name (game build ${game.build}) and the wiki's difficulty range.
export const structureObjectivesCheckedAt = ${JSON.stringify(wiki.retrievedAt)};
export const structureObjectives = ${JSON.stringify(objectives, null, 1)};
`;
await writeFile(new URL('../dist/data/structure-objectives.js', import.meta.url), out);
console.log(`${Object.keys(objectives).length} structures`);
